      "path": "out/p4m-start-review-20260920/review.py",
      "content": "#!/usr/bin/env python3\n\"\"\"Read-only review of the P4M start-control 12-case run (kernel 00089, observer v7).\n\nPure analysis helper.  It reads the archived run artifacts and writes exactly one\nderived file (review.json) next to this script.  It never writes into the run\ndirectory, never edits an original artifact, and deliberately uses\nobservations-unique.log instead of the full console.raw.log.\n\nInvocation:\n    python3 out/p4m-start-review-20260920/review.py\n\nExit code:\n    0  every functional check passed\n    1  at least one functional check failed\nWarnings (short-A1 hrtimer message, null hashes, non-frozen status, ...) are\nreported separately and never change the exit code.  No case is dropped,\nincluding the short-A1 outlier.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport hashlib\nimport json\nimport re\nimport sys\nfrom pathlib import Path\n\n# ---------------------------------------------------------------------------\n# Locations\n# ---------------------------------------------------------------------------\nREVIEW_DIR = Path(__file__).resolve().parent\nREPO_ROOT = REVIEW_DIR.parent.parent\nRUN_REL = \"out/mac-p4m-start-20260920-211940-run-46nvmwgi\"\nRUN_DIR = REPO_ROOT / RUN_REL\nREVIEW_JSON = REVIEW_DIR / \"review.json\"\n\nINPUT_FILES = (\n    (\"records\", \"records.json\"),\n    (\"observations\", \"observations-unique.log\"),\n    (\"run\", \"run.json\"),\n    (\"delivery\", \"delivery.json\"),\n)\n\n# ---------------------------------------------------------------------------\n# Frozen expectations (values taken from the records themselves)\n# ---------------------------------------------------------------------------\nEXPECTED_KERNEL = \"6.5.0-rc2-00089-gefd9461d6459\"\nEXPECTED_BIT_SHA256 = (\n    \"7af1ccbcb36306d5439eeab9b39d8fdfa266f70ebfedd7c0a4f0dd1be6825d0e\")\nEXPECTED_PAYLOAD_SHA256 = (\n    \"fc8e8a73d3e71e127d7d995518f668382391ef0920418d16ccb66d716543291d\")\nLONG_PATTERN = \"BPPBBPPB\"\nSHORT_COUNT = 4\nCYCLE_NS = 20\nMIB = 1024 * 1024\nNO_AGGRESSOR = 0xFFFFFFFF\n\n# ---------------------------------------------------------------------------\n# Log grammar (only the line kinds this review needs)\n# ---------------------------------------------------------------------------\nRE_CASE_BEGIN = re.compile(\n    r\"^P4M: case_begin id=(?P<id>\\S+) condition=(?P<condition>\\S+) \"\n    r\"kind=(?P<kind>\\S+) mode=(?P<mode>\\S+) taint_before=(?P<taint>\\d+) \"\n    r\".*? total=(?P<total>\\d+) argv=(?P<argv>.*)$\")\nRE_START = re.compile(\n    r\"idma_batch_start version=(?P<version>\\d+) seq=(?P<seq>\\d+) \"\n    r\"method=(?P<method>\\S+) v_did=(?P<v_did>\\d+) a_did=(?P<a_did>\\d+) \"\n    r\"attempted=(?P<attempted>\\d+) has_a=(?P<has_a>\\d+) \"\n    r\"a_triggered=(?P<a_triggered>\\d+) v_triggered=(?P<v_triggered>\\d+) \"\n    r\"a_id=(?P<a_id>\\d+) v_id=(?P<v_id>\\d+) a_begin_ns=(?P<a_begin>\\d+) \"\n    r\"a_end_ns=(?P<a_end>\\d+) v_begin_ns=(?P<v_begin>\\d+) \"\n    r\"v_end_ns=(?P<v_end>\\d+) irq_span_ns=(?P<irq_span>\\d+) \"\n    r\"a_to_v_ns=(?P<a_to_v>\\d+) error=(?P<error>-?\\d+)\")\nRE_OBS_TIME = re.compile(\n    r\"idma_batch_obs seq=(?P<seq>\\d+) part=time valid=(?P<valid>\\d+) \"\n    r\"status=(?P<status>\\S+) v_did=(?P<v_did>\\d+) a_did=(?P<a_did>\\d+) \"\n    r\"cycles=(?P<cycles>\\d+) \")\nRE_HRTIMER = re.compile(\n    r\"^\\[\\s*(?P<ts>\\d+\\.\\d+)\\] hrtimer: interrupt took (?P<took>\\d+) ns\")\nRE_FINAL_TAINT = re.compile(r\"P4M: final_taint=(?P<taint>\\d+)\")\nRE_COLLECT = re.compile(\n    r\"P4M: final_exit=(?P<exit>-?\\d+) collection_failed=(?P<failed>\\d+) \"\n    r\"mode=(?P<mode>\\S+) cases_done=(?P<done>\\d+) total=(?P<total>\\d+)\")\nRE_COMPLETE = re.compile(\n    r\"P4M: complete ok mode=(?P<mode>\\S+) cases=(?P<cases>\\d+) \"\n    r\"total=(?P<total>\\d+)\")\nRE_HOST_EXIT = re.compile(r\"P4M_START_HOST_EXIT=(?P<exit>-?\\d+)\")\n\n\ndef sha256_file(path: Path) -> str:\n    digest = hashlib.sha256()\n    with open(path, \"rb\") as handle:\n        for block in iter(lambda: handle.read(1 << 20), b\"\"):\n            digest.update(block)\n    return digest.hexdigest()\n\n\ndef load_json(path: Path):\n    with open(path, \"r\", encoding=\"utf-8\") as handle:\n        return json.load(handle)\n\n\ndef parse_unique_log(path: Path) -> dict:\n    cases, starts, obs_time, hrtimers, tail = [], {}, {}, [], {}\n    with open(path, \"r\", encoding=\"utf-8\", errors=\"replace\") as handle:\n        for raw in handle:\n            line = raw.rstrip(\"\\n\")\n\n            match = RE_CASE_BEGIN.match(line)\n            if match:\n                cases.append({\n                    \"id\": match.group(\"id\"),\n                    \"condition\": match.group(\"condition\"),\n                    \"kind\": match.group(\"kind\"),\n                    \"mode\": match.group(\"mode\"),\n                    \"taint_before\": int(match.group(\"taint\")),\n                    \"total\": int(match.group(\"total\")),\n                    \"argv\": match.group(\"argv\"),\n                })\n                continue\n\n            match = RE_START.search(line)\n            if match:\n                starts[int(match.group(\"seq\"))] = {\n                    \"version\": int(match.group(\"version\")),\n                    \"method\": match.group(\"method\"),\n                    \"v_did\": int(match.group(\"v_did\")),\n                    \"a_did\": int(match.group(\"a_did\")),\n                    \"attempted\": int(match.group(\"attempted\")),\n                    \"has_a\": int(match.group(\"has_a\")),\n                    \"a_triggered\": int(match.group(\"a_triggered\")),\n                    \"v_triggered\": int(match.group(\"v_triggered\")),\n                    \"a_id\": int(match.group(\"a_id\")),\n                    \"v_id\": int(match.group(\"v_id\")),\n                    \"a_begin_ns\": int(match.group(\"a_begin\")),\n                    \"a_end_ns\": int(match.group(\"a_end\")),\n                    \"v_begin_ns\": int(match.group(\"v_begin\")),\n                    \"v_end_ns\": int(match.group(\"v_end\")),\n                    \"irq_span_ns\": int(match.group(\"irq_span\")),\n                    \"a_to_v_ns\": int(match.group(\"a_to_v\")),\n                    \"error\": int(match.group(\"error\")),\n                }\n                continue\n\n            match = RE_OBS_TIME.search(line)\n            if match:\n                obs_time[int(match.group(\"seq\"))] = {\n                    \"valid\": int(match.group(\"valid\")),\n                    \"status\": match.group(\"status\"),\n                    \"cycles\": int(match.group(\"cycles\")),\n                }\n                continue\n\n            match = RE_HRTIMER.match(line)\n            if match:\n                stamp = float(match.group(\"ts\"))\n                hrtimers.append({\n                    \"ts_s\": stamp,\n                    \"ts_ns\": round(stamp * 1e9),\n                    \"took_ns\": int(match.group(\"took\")),\n                })\n                continue\n\n            match = RE_FINAL_TAINT.search(line)\n            if match:\n                tail[\"final_taint\"] = int(match.group(\"taint\"))\n                continue\n\n            match = RE_COLLECT.search(line)\n            if match:\n                tail[\"final_exit\"] = int(match.group(\"exit\"))\n                tail[\"collection_failed\"] = int(match.group(\"failed\"))\n                tail[\"mode\"] = match.group(\"mode\")\n                tail[\"cases_done\"] = int(match.group(\"done\"))\n                tail[\"total\"] = int(match.group(\"total\"))\n                continue\n\n            match = RE_COMPLETE.search(line)\n            if match:\n                tail[\"complete_ok\"] = True\n                tail[\"complete_cases\"] = int(match.group(\"cases\"))\n                continue\n\n            match = RE_HOST_EXIT.search(line)\n            if match:\n                tail[\"host_exit\"] = int(match.group(\"exit\"))\n                continue\n\n    return {\n        \"cases\": cases,\n        \"starts\": starts,\n        \"obs_time\": obs_time,\n        \"hrtimers\": hrtimers,\n        \"tail\": tail,\n    }\n\n\ndef p4m_window_ok(window, transfers: int, has_a: bool) -> bool:\n    \"\"\"Mirror the core P4M window identities (driver idma.c:1403-1444).\"\"\"\n    if not window or len(window) < 16:\n        return False\n    issue, done = window[2], window[3]\n    open_infl, close_infl = window[4], window[5]\n    carry = window[6]\n    start_id, end_id = window[8], window[9]\n    first, last = window[10], window[11]\n    if window[12] != 0:\n        return False\n    if window[13] != transfers or window[14] != transfers:\n        return False\n    if not has_a:\n        return all(window[i] == 0 for i in range(2, 13))\n    if open_infl > 1 or close_infl > 1 or carry > 1:\n        return False\n    if open_infl + issue != done + close_infl:\n        return False\n    if carry > open_infl or carry > done:\n        return False\n    if bool(open_infl) != bool(start_id):\n        return False\n    if bool(close_infl) != bool(end_id):\n        return False\n    if done:\n        if not first or not last or last != first + done - 1:\n            return False\n        if open_infl and first != start_id:\n            return False\n        if close_infl and end_id != last + 1:\n            return False\n    return True\n\n\ndef build_cases(records, log) -> list:\n    rows = []\n    for index, record in enumerate(records):\n        seq = index + 1\n        meta = log[\"cases\"][index] if index < len(log[\"cases\"]) else {}\n        start = log[\"starts\"].get(seq)\n        obs = log[\"obs_time\"].get(seq)\n        p4m = record.get(\"p4m\") or {}\n        result = record.get(\"result\") or {}\n        victim = result.get(\"victim\") or {}\n        aggressor = result.get(\"aggressor\")\n        transfers = (record.get(\"input\") or {}).get(\"victim_transfers\")\n        cycles = p4m.get(\"cycles\") if p4m else (obs.get(\"cycles\") if obs else None)\n        hardware_ns = p4m.get(\"hardware_window_ns\") if p4m else (\n            cycles * CYCLE_NS if cycles else None)\n        completed_bytes = victim.get(\"completed_bytes\")\n        rate_mib_s = None\n        if completed_bytes and hardware_ns:\n            rate_mib_s = completed_bytes / MIB / (hardware_ns / 1e9)\n        rows.append({\n            \"seq\": seq,\n            \"case\": meta.get(\"id\"),\n            \"condition\": meta.get(\"condition\"),\n            \"kind\": meta.get(\"kind\"),\n            \"mode\": meta.get(\"mode\"),\n            \"schema\": record.get(\"schema\"),\n            \"success\": record.get(\"success\"),\n            \"status\": result.get(\"status\"),\n            \"victim_transfers\": transfers,\n            \"victim_submitted\": victim.get(\"submitted\"),\n            \"victim_completed\": victim.get(\"completed\"),\n            \"victim_completed_bytes\": completed_bytes,\n            \"victim_data_errors\": victim.get(\"data_errors\"),\n            \"victim_quarantined\": victim.get(\"quarantined\"),\n            \"aggressor_present\": aggressor is not None,\n            \"aggressor_completed_bytes\": (aggressor or {}).get(\"completed_bytes\"),\n            \"aggressor_data_errors\": (aggressor or {}).get(\"data_errors\"),\n            \"aggressor_quarantined\": (aggressor or {}).get(\"quarantined\"),\n            \"cycles\": cycles,\n            \"hardware_window_ns\": hardware_ns,\n            \"victim_hw_mib_s\": rate_mib_s,\n            \"p4m_sequence\": p4m.get(\"sequence\"),\n            \"p4m_observer_status\": p4m.get(\"observer_status\"),\n            \"p4m_closed\": p4m.get(\"closed\"),\n            \"p4m_conservation\": p4m.get(\"conservation\"),\n            \"p4m_has_a\": p4m.get(\"has_a\"),\n            \"p4m_strict_preopening\": p4m.get(\"strict_preopening_inflight\"),\n            \"p4m_a_completed_jobs_window\": p4m.get(\"a_completed_jobs_window\"),\n            \"p4m_a_progress_window_bytes\": p4m.get(\"a_progress_window_bytes\"),\n            \"p4m_a_started_before_bytes\": p4m.get(\"a_started_before_window_bytes\"),\n            \"p4m_a_bytes_per_second\": p4m.get(\"a_completed_bytes_per_second\"),\n            \"p4m_task_error_mask\": p4m.get(\"task_error_mask\"),\n            \"p4m_opening_inflight_id\": p4m.get(\"a_opening_inflight_id\"),\n            \"semantics_calibration\": (record.get(\"semantics\") or {}).get(\"calibration\"),\n            \"start\": start,\n            \"obs_time\": obs,\n            \"window_ok\": (p4m_window_ok(p4m.get(\"raw_window\"), transfers,\n                                        bool(p4m.get(\"has_a\")))\n                          if p4m else None),\n        })\n    return rows\n\n\ndef main() -> int:\n    checks, warnings = [], []\n\n    def chk(name, ok, detail=\"\"):\n        checks.append({\"name\": name, \"ok\": bool(ok), \"detail\": detail})\n\n    def warn(name, detail):\n        warnings.append({\"name\": name, \"detail\": detail})\n\n    inputs_sha, missing = {}, []\n    for _key, name in INPUT_FILES:\n        path = RUN_DIR / name\n        if path.exists():\n            inputs_sha[name] = sha256_file(path)\n        else:\n            inputs_sha[name] = None\n            missing.append(name)\n    chk(\"inputs_present\", not missing, \"missing: %s\" % (missing or \"none\"))\n\n    records = load_json(RUN_DIR / \"records.json\")\n    run = load_json(RUN_DIR / \"run.json\")\n    delivery_path = RUN_DIR / \"delivery.json\"\n    delivery = load_json(delivery_path) if delivery_path.exists() else {}\n    log = parse_unique_log(RUN_DIR / \"observations-unique.log\")\n\n    rows = build_cases(records, log)\n\n    # ---- core functional checks -----------------------------------------\n    chk(\"records_len_is_12\", len(records) == 12, \"len=%d\" % len(records))\n    chk(\"records_all_success\",\n        all(r.get(\"success\") is True and r.get(\"error\") is None\n            and r.get(\"errno\") == 0 for r in records))\n    chk(\"records_result_status_zero\",\n        all(r.get(\"status\") == 0 for r in rows),\n        \"statuses=%s\" % sorted({r.get(\"status\") for r in rows}))\n    chk(\"victim_submitted_completed_match\",\n        all(r[\"victim_submitted\"] == r[\"victim_completed\"] == r[\"victim_transfers\"]\n            for r in rows))\n    chk(\"victim_data_errors_zero\",\n        all(r[\"victim_data_errors\"] == 0 and r[\"victim_quarantined\"] == 0\n            for r in rows))\n    chk(\"aggressor_data_errors_zero\",\n        all((r[\"aggressor_data_errors\"] in (None, 0))\n            and (r[\"aggressor_quarantined\"] in (None, 0)) for r in rows))\n    chk(\"p4m_blocks_wellformed\",\n        all(r[\"p4m_observer_status\"] == 4 and r[\"p4m_closed\"] is True\n            and r[\"p4m_conservation\"] is True and r[\"p4m_task_error_mask\"] == 0\n            for r in rows if r[\"p4m_sequence\"] is not None))\n    chk(\"p4m_raw_window_conserved\",\n        all(r[\"window_ok\"] for r in rows if r[\"window_ok\"] is not None))\n    chk(\"p4m_has_a_matches_aggressor\",\n        all(r[\"p4m_has_a\"] == r[\"aggressor_present\"]\n            for r in rows if r[\"p4m_sequence\"] is not None))\n    chk(\"p4m_sequence_matches_index\",\n        all(r[\"p4m_sequence\"] == r[\"seq\"]\n            for r in rows if r[\"p4m_sequence\"] is not None))\n    chk(\"p4m_cycles_match_log\",\n        all(r[\"obs_time\"] is not None and r[\"obs_time\"][\"cycles\"] == r[\"cycles\"]\n            for r in rows))\n\n    # ---- ordering / roles ----------------------------------------------\n    chk(\"log_case_count_is_12\", len(log[\"cases\"]) == 12,\n        \"cases=%d\" % len(log[\"cases\"]))\n    chk(\"log_short_then_long\",\n        [c[\"mode\"] for c in log[\"cases\"][:SHORT_COUNT]] == [\"p4m\"] * SHORT_COUNT\n        and [c[\"mode\"] for c in log[\"cases\"][SHORT_COUNT:]]\n        == [\"batch\", \"p4m\", \"p4m\", \"batch\", \"batch\", \"p4m\", \"p4m\", \"batch\"])\n    long_pattern = \"\".join(\n        \"B\" if c[\"mode\"] == \"batch\" else \"P\" for c in log[\"cases\"][SHORT_COUNT:])\n    chk(\"log_long_pattern_bppbbppb\", long_pattern == LONG_PATTERN,\n        \"pattern=%s\" % long_pattern)\n    chk(\"log_seq_contiguous\", sorted(log[\"starts\"]) == list(range(1, 13)),\n        \"seqs=%s\" % sorted(log[\"starts\"]))\n    chk(\"log_start_wellformed\",\n        all(s[\"attempted\"] == 1 and s[\"error\"] == 0\n            and s[\"a_begin_ns\"] <= s[\"a_end_ns\"] <= s[\"v_begin_ns\"] <= s[\"v_end_ns\"]\n            for s in log[\"starts\"].values()))\n    chk(\"log_obs_time_valid\",\n        all(o[\"valid\"] == 1 and o[\"status\"] == \"0x4\"\n            for o in log[\"obs_time\"].values()))\n    tail = log[\"tail\"]\n    chk(\"log_tail_clean\",\n        tail.get(\"final_taint\") == 0 and tail.get(\"final_exit\") == 0\n        and tail.get(\"collection_failed\") == 0 and tail.get(\"cases_done\") == 12\n        and tail.get(\"host_exit\") == 0 and tail.get(\"complete_ok\") is True,\n        json.dumps(tail, sort_keys=True))\n\n    # ---- provenance -----------------------------------------------------\n    chk(\"kernel_observed_eq_expected\",\n        run.get(\"observed_kernel\") == EXPECTED_KERNEL\n        and run.get(\"expected_kernel\") == EXPECTED_KERNEL,\n        \"%s / %s\" % (run.get(\"observed_kernel\"), run.get(\"expected_kernel\")))\n    chk(\"run_bit_expected_matches_delivery\",\n        run.get(\"bit\", {}).get(\"expected_sha256\") == EXPECTED_BIT_SHA256\n        and delivery.get(\"artifacts\", {}).get(\"ariane_xilinx.bit\", {}).get(\"sha256\")\n        == EXPECTED_BIT_SHA256\n        and delivery.get(\"copied_sha256\", {}).get(\"ariane_xilinx.bit\")\n        == EXPECTED_BIT_SHA256\n        and delivery.get(\"reuse\", {}).get(\"bit_sha256\") == EXPECTED_BIT_SHA256)\n    chk(\"payload_expected_consistent\",\n        run.get(\"expected_payload_sha256\") == EXPECTED_PAYLOAD_SHA256\n        and delivery.get(\"artifacts\", {}).get(\"fw_payload.bin\", {}).get(\"sha256\")\n        == EXPECTED_PAYLOAD_SHA256\n        and delivery.get(\"copied_sha256\", {}).get(\"fw_payload.bin\")\n        == EXPECTED_PAYLOAD_SHA256)\n    chk(\"no_fpga_rebuild\",\n        delivery.get(\"build_status\", {}).get(\"fpga\", {}).get(\"rebuilt\") is False\n        and delivery.get(\"reuse\", {}).get(\"rebuilt\") is False)\n    chk(\"board_not_claimed_tested\",\n        delivery.get(\"build_status\", {}).get(\"board\", {}).get(\"board_tested\") is False)\n\n    # ---- warnings (never fail the run, never delete a case) -------------\n    if log[\"hrtimers\"]:\n        for event in log[\"hrtimers\"]:\n            nearest, best = None, None\n            for seq, start in log[\"starts\"].items():\n                for label in (\"a_begin_ns\", \"v_end_ns\"):\n                    delta = event[\"ts_ns\"] - start[label]\n                    if best is None or abs(delta) < abs(best):\n                        nearest, best = (seq, label), delta\n            warn(\"hrtimer_interrupt_warning\",\n                 \"ts_ns=%d took_ns=%d nearest=%s delta_ns=%d\"\n                 % (event[\"ts_ns\"], event[\"took_ns\"], nearest, best))\n    else:\n        warn(\"hrtimer_interrupt_warning\", \"none observed in observations-unique.log\")\n    for row in rows:\n        if row[\"start\"] and row[\"start\"][\"a_to_v_ns\"]:\n            pass\n    a1 = next((r for r in rows if r[\"case\"] == \"start-s2-a1-gap0\"), None)\n    if a1 and a1[\"start\"]:\n        warn(\"short_a1_span_outlier\",\n             \"seq=%d irq_span_ns=%d a_to_v_ns=%d (case retained)\"\n             % (a1[\"seq\"], a1[\"start\"][\"irq_span_ns\"], a1[\"start\"][\"a_to_v_ns\"]))\n    warn(\"bit_hash_not_verified\",\n         \"run.bit.sha256=%r hash_verified=%r software_sha256=%r\"\n         % (run.get(\"bit\", {}).get(\"sha256\"),\n            run.get(\"bit\", {}).get(\"hash_verified\"), run.get(\"software_sha256\")))\n    warn(\"acceptance_flag